const STATUS = {
  suggested: 'Suggested', planned: 'Planned', learning: 'Learning',
  practicing: 'Practicing', ready: 'Performance ready', archived: 'Archived'
};
const ATTENDANCE = {attending:'Attending', maybe:'Maybe', unavailable:'Unavailable', no_response:'No response'};
const COLORS = ['#5c9d8b','#bb795f','#8876ba','#7195bd','#c18f3f','#bd6b84','#629b58','#5d85a2'];
const app = document.getElementById('app');
const modal = document.getElementById('modal');
const state = {member:null,band:null,members:[],allMembers:[],songs:[],dashboard:null,locations:[],rehearsals:[],tab:'songs',practice:'availability',authMode:'login',authNotice:'',configured:false,songsQuery:{},weekStart:null,availability:[],overlap:null,searchTimer:null};

function esc(value='') { return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function initials(name='?') { return name.trim().split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase() || '?'; }
function avatar(member, small=false) { return `<span class="avatar" title="${esc(member.display_name)}" style="background:${esc(member.color||'#cfe3d9')};${small?'':''}">${esc(initials(member.display_name))}</span>`; }
function toast(message, error=false) { const host=document.getElementById('toast-region');if(!host)return;const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;host.append(el);setTimeout(()=>el.remove(),3600); }
async function api(path, options={}) {
  const init={method:options.method||'GET',credentials:'same-origin',headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}};
  if(options.body) init.body=JSON.stringify(options.body);
  const response=await fetch(path,init);let data={};try{data=await response.json()}catch{}
  if(!response.ok){const err=new Error(data.error||`Request failed (${response.status})`);err.status=response.status;err.details=data.details;throw err}
  return data;
}
function localDateString(dateObj=new Date(),tz=state.band?.timezone||'America/Toronto') {
  const parts=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(dateObj);
  const val=Object.fromEntries(parts.map(p=>[p.type,p.value]));return `${val.year}-${val.month}-${val.day}`;
}
function addDays(iso, amount) { const d=new Date(`${iso}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+amount);return d.toISOString().slice(0,10); }
function mondayOf(iso) { const d=new Date(`${iso}T12:00:00Z`);const offset=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-offset);return d.toISOString().slice(0,10); }
function fmtDate(iso,opts={weekday:'short',month:'short',day:'numeric'}) { if(!iso)return '';return new Intl.DateTimeFormat('en-CA',{...opts,timeZone:state.band?.timezone||'America/Toronto'}).format(new Date(`${iso.slice(0,10)}T12:00:00Z`)); }
function fmtInstant(iso,opts={weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}) { return new Intl.DateTimeFormat('en-CA',{...opts,timeZone:state.band?.timezone||'America/Toronto'}).format(new Date(iso)); }
function fmtTime(time) { if(!time)return '';const [h,m]=time.split(':').map(Number);const d=new Date();d.setHours(h,m,0,0);return new Intl.DateTimeFormat('en-CA',{hour:'numeric',minute:'2-digit'}).format(d); }
function durationText(minutes) { if(minutes==null)return 'Duration not set';const h=Math.floor(minutes/60),m=minutes%60;return h?`${h} hr${h===1?'':'s'}${m?` ${m} min`:''}`:`${m} min`; }
function money(amount) { return new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(Number(amount||0)); }
function statusPill(status) { return `<span class="status status-${esc(status)}">${esc(STATUS[status]||status)}</span>`; }
function priorityDots(n) { return `<span class="priority-dots" aria-label="Priority ${n} of 5">${[1,2,3,4,5].map(i=>`<i class="${i<=n?'on':''}"></i>`).join('')}</span>`; }
function emptyState(icon,title,text,button='') { return `<div class="empty-state"><div class="empty-icon">${icon}</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${button}</div>`; }
function selectOptions(options,selected='',emptyLabel='Choose…') { return `<option value="">${esc(emptyLabel)}</option>${options.map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(selected)?'selected':''}>${esc(o.label)}</option>`).join('')}`; }
function memberOptions(selected='',emptyLabel='Unassigned') { return selectOptions(state.members.map(m=>({value:m.id,label:m.display_name})),selected,emptyLabel); }
function memberChecks(name,selected=[]) { return `<div class="member-checks">${state.members.map(m=>`<label class="check-pill"><input type="checkbox" name="${name}" value="${m.id}" ${selected.includes(m.id)?'checked':''}> <span class="dot" style="background:${esc(m.color)};width:8px;height:8px;border-radius:50%"></span>${esc(m.display_name)}</label>`).join('')}</div>`; }
function formValue(fd,key) { const value=fd.get(key);return value==null?'':String(value).trim(); }
function formIds(form,name) { return [...form.querySelectorAll(`input[name="${name}"]:checked`)].map(i=>Number(i.value)); }
function setFormError(message, details) { const box=modal.querySelector('#form-error');if(box){box.textContent=message;box.hidden=false}const reload=modal.querySelector('#reload-conflict');if(reload&&details){reload.hidden=false;modal.dataset.conflict=JSON.stringify(details)} }
function showModal(title,subtitle,body) { if(modal.open)modal.close();modal.innerHTML=`<div class="modal-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button type="button" class="icon-btn" aria-label="Close dialog" data-action="close-modal">×</button></div><div class="modal-body">${body}</div>`;modal.showModal(); }
function closeModal() { if(modal.open)modal.close();modal.innerHTML=''; }

async function boot() {
  const resetToken=new URLSearchParams(location.hash.slice(1)).get('reset');
  if(resetToken){state.authMode='reset';renderAuth({configured:true});return}
  try {
    const session=await api('/api/me');state.member=session.member;state.band=session.band;
    state.weekStart=mondayOf(localDateString());
    await loadMembers();await loadSongs();await loadDashboard();renderApp();
  } catch(error) {
    const status=await api('/api/status').catch(()=>({configured:true}));
    state.configured=Boolean(status.configured);
    state.authMode=new URLSearchParams(location.search).get('token')?'join':(status.configured?'login':'signup');
    renderAuth(status);
  }
}
async function loadMembers(){const r=await api('/api/members');state.members=r.members;}
async function loadAllMembers(){const r=await api('/api/members?manage=1');state.allMembers=r.members;}
async function loadSongs(){const p=new URLSearchParams(state.songsQuery);const r=await api(`/api/songs${p.toString()?`?${p}`:''}`);state.songs=r.songs;}
async function loadDashboard(){state.dashboard=await api('/api/dashboard');}
async function loadRehearsals(){const r=await api(`/api/rehearsals?from=${encodeURIComponent(new Date().toISOString())}`);state.rehearsals=r.rehearsals;}
async function loadLocations(){const r=await api('/api/locations');state.locations=r.locations;}
async function loadAvailability(){const from=state.weekStart||mondayOf(localDateString());const r=await api(`/api/availability?from=${from}&to=${addDays(from,6)}`);state.availability=r.entries;}

function renderAuth(status={configured:true}) {
  const token=new URLSearchParams(location.search).get('token')||'';
  const mode=state.authMode;
  const resetToken=new URLSearchParams(location.hash.slice(1)).get('reset')||'';
  const headings={login:['Sign in to your band','Enter your band name, email, and password.'],signup:['Create a band space','Set up a private home for your band’s songs, plans, and practice.'],join:['Join your band','Create your member account to join the shared band space.'],forgot:['Reset your password','Enter your band name and account email. We’ll send a one-time reset link if they match.'],reset:['Choose a new password','Set a new password for your Bandroom account. The reset link works once and expires after 30 minutes.']};
  const [title,sub]=headings[mode]||headings.login;
  const tabs=['login','signup'].includes(mode)?`<div class="auth-tabs"><button type="button" class="${mode==='login'?'active':''}" data-auth-mode="login">Sign in</button><button type="button" class="${mode==='signup'?'active':''}" data-auth-mode="signup">Create a band</button></div>`:'';
  const bandField=['login','signup','forgot'].includes(mode)?`<div class="field full"><label for="band-name">Band name</label><input id="band-name" class="input" name="band_name" required maxlength="100" autocomplete="organization-title" placeholder="${mode==='login'?'Enter your band name':'e.g. The Sunday Set'}"><span class="help">${mode==='login'?'Use the exact name of the band workspace.':mode==='forgot'?'Use the band workspace you sign in to.':'Band names must be unique on this site.'}</span></div>`:'';
  const accountFields=mode==='reset'?`<input type="hidden" name="token" value="${esc(resetToken)}"><div class="field full"><label for="password">New password</label><input id="password" class="input" type="password" name="password" required minlength="10" maxlength="200" autocomplete="new-password" placeholder="At least 10 characters"></div><div class="field full"><label for="password-confirmation">Confirm new password</label><input id="password-confirmation" class="input" type="password" name="password_confirmation" required minlength="10" maxlength="200" autocomplete="new-password" placeholder="Enter it again"></div>`:
    mode==='forgot'?`<div class="field full"><label for="email">Account email</label><input id="email" class="input" type="email" name="email" required maxlength="254" autocomplete="email" placeholder="you@example.com"></div>`:
    `${mode==='join'?`<input type="hidden" name="token" value="${esc(token)}"><div class="field full"><label for="invite-token">Invitation link token</label><input id="invite-token" class="input" name="token_display" value="${esc(token)}" disabled><span class="help">This invitation is private to your band.</span></div>`:''}${mode!=='login'?`<div class="field full"><label for="display-name">Display name</label><input id="display-name" class="input" name="display_name" required maxlength="80" autocomplete="name" placeholder="How the band knows you"></div>`:''}<div class="field full"><label for="email">Email</label><input id="email" class="input" type="email" name="email" required maxlength="254" autocomplete="email" placeholder="you@example.com"></div><div class="field full"><label for="password">Password</label><input id="password" class="input" type="password" name="password" required minlength="10" maxlength="200" autocomplete="${mode==='login'?'current-password':'new-password'}" placeholder="At least 10 characters">${mode==='login'?'<span class="help">Your password is stored securely as a salted hash.</span>':''}</div>`;
  const buttonText={login:'Sign in',signup:'Create band space',join:'Join the band',forgot:'Email me a reset link',reset:'Save new password'}[mode]||'Continue';
  const extra=mode==='login'?`<button type="button" class="auth-link" data-auth-mode="forgot">Forgot your password?</button>`:['forgot','reset'].includes(mode)?`<button type="button" class="auth-link" data-auth-mode="login">Back to sign in</button>`:mode==='signup'?`<p class="help" style="margin-top:18px">You’ll become the band admin and can invite the rest of the members.</p>`:'';
  app.innerHTML=`<main class="auth-shell"><section class="auth-art"><div class="auth-logo"><span class="brand-mark">♫</span> bandroom</div><div class="auth-message"><span class="eyebrow">A shared space for your sound</span><h1>Good music starts with being in sync.</h1><p>Keep the songs, rehearsal plans, and the people behind them all in one place.</p><div class="soundwaves">${[38,61,30,75,45,90,28,63,39,80,44,66,28,72,52,93,41,75,32,58].map(h=>`<i style="--h:${h}%"></i>`).join('')}</div></div><div style="font-size:11px;color:#a9c0b6">Private to your band · Built for the next practice</div></section><section class="auth-side"><div class="auth-card"><h2>${title}</h2><p class="subtext">${sub}</p>${tabs}${state.authNotice?`<div class="success-box" role="status">${esc(state.authNotice)}</div>`:''}<form id="auth-form" data-mode="${mode}" class="form-grid">${bandField}${accountFields}<div class="field full"><div id="form-error" class="error-text" hidden></div><button class="btn btn-primary" type="submit">${buttonText} <span aria-hidden="true">→</span></button></div></form>${extra}</div></section></main>`;
}

function renderShell() {
  const name=state.member.display_name;
  return `<header class="topbar"><div class="brand"><span class="brand-mark">♫</span><span>${esc(state.band.name)}</span></div><nav class="topnav" aria-label="Main navigation"><button class="nav-tab ${state.tab==='songs'?'active':''}" data-tab="songs"><span>♫</span> Songs</button><button class="nav-tab ${state.tab==='practice'?'active':''}" data-tab="practice"><span>◷</span> Practice</button></nav><div class="top-actions"><span class="timezone-pill">${esc(state.band.timezone)}</span><div class="user-menu"><button class="user-button" data-action="user-menu" aria-expanded="false">${avatar(state.member)}<span class="user-name">${esc(name)}</span><span aria-hidden="true">⌄</span></button><div class="user-popover" id="user-popover"><button data-action="profile">My profile</button>${state.member.role==='admin'?'<button data-action="invite">Invite a member</button><button data-action="manage-members">Manage members</button>':''}<button data-action="logout">Sign out</button></div></div></div></header>`;
}

function renderApp() {
  if(!state.member){renderAuth();return}
  const page=state.tab==='songs'?renderSongsPage():renderPracticePage();
  app.innerHTML=`<div class="app-shell">${renderShell()}${page}</div>`;
  if(state.tab==='practice') refreshPractice().catch(e=>toast(e.message,true));
}

function renderSongsPage() {
  const d=state.dashboard||{};
  const next=d.next_rehearsal;
  const nextContent=next?`<div class="next-title">${esc(next.title)}</div><div class="next-meta">${esc(fmtInstant(next.start_utc,{weekday:'long',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))}<br>${esc(next.location_name_snapshot||'Location to be decided')} · ${durationText(next.duration_minutes)}<br><span class="status status-${esc(next.status)}">${esc(next.status)}</span></div>`:`<div class="next-title">Nothing on the calendar yet</div><div class="next-meta">Find a time that works and plan your next rehearsal.</div><div style="margin-top:12px"><button class="btn btn-small" data-tab="practice">Open practice planner</button></div>`;
  const planned=(d.planned_songs||[]).length?`<div class="dash-song-list">${d.planned_songs.slice(0,4).map(x=>`<span class="song-chip">${esc(x.title)}</span>`).join('')}${d.planned_songs.length>4?`<span class="song-chip">+${d.planned_songs.length-4} more</span>`:''}</div>`:`<p class="muted-note">No songs planned yet.</p>`;
  const practice=(d.needs_practice||[]).length?`<div class="practice-mini">${d.needs_practice.slice(0,3).map(x=>`<button data-action="song-detail" data-id="${x.id}"><span>${esc(x.title)}</span>${priorityDots(x.priority)}</button>`).join('')}</div>`:`<p class="muted-note">All set for now. Add a song you’re learning.</p>`;
  const updates=(d.recent_updates||[]).length?`<div class="activity-list">${d.recent_updates.slice(0,4).map(x=>`<div class="activity-row">${avatar({display_name:x.display_name,color:x.color})}<div><strong>${esc(x.display_name)}</strong> ${esc(x.action)} <strong>${esc(x.entity_title)}</strong><time>${esc(fmtInstant(x.created_at,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))}</time></div></div>`).join('')}</div>`:`<p class="muted-note">Member updates will show up here.</p>`;
  const announcements=(d.announcements||[]).length?`<div class="announcement-list">${d.announcements.map(x=>{const canManage=x.member_id===state.member.id||state.member.role==='admin';return `<article class="announcement-item">${avatar({display_name:x.display_name,color:x.color})}<div class="announcement-content"><div class="announcement-byline"><strong>${esc(x.display_name)}</strong><time datetime="${esc(x.created_at)}">${esc(fmtInstant(x.created_at,{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}))}${x.version>1?` · Updated ${esc(fmtInstant(x.updated_at,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))}`:''}</time>${x.is_pinned?'<span class="announcement-pin-label">Pinned</span>':''}</div><p>${esc(x.body)}</p><div class="announcement-actions">${canManage?`<button class="btn btn-small" data-action="edit-announcement" data-id="${x.id}">Edit</button><button class="btn btn-small btn-danger" data-action="delete-announcement" data-id="${x.id}" data-version="${x.version}">Delete</button>`:''}${state.member.role==='admin'?`<button class="btn btn-small" data-action="pin-announcement" data-id="${x.id}" data-version="${x.version}" data-pinned="${x.is_pinned?'0':'1'}">${x.is_pinned?'Unpin':'Pin'}</button>`:''}</div></div></article>`}).join('')}</div>`:`<div class="announcement-empty">No announcements yet. Post an update for your band here.</div>`;
  return `<main class="page-wrap"><div class="page-heading"><div><span class="eyebrow">Shared band workspace</span><h1>Songs that bring us together.</h1><p>${d.songs_count||0} active songs · ${d.member_count||state.members.length} members · ${esc(state.band.timezone)}</p></div><div class="actions"><button class="btn btn-primary" data-action="new-song"><span>＋</span> Add a song</button></div></div><section class="announcement-panel" aria-labelledby="announcement-heading"><div class="announcement-head"><div><span class="eyebrow">For everyone in ${esc(state.band.name)}</span><h2 id="announcement-heading">Announcements</h2></div><p>Share rehearsal updates, plans, or anything the band should know.</p></div><form id="announcement-form"><label class="sr-only" for="announcement-body">Write an announcement</label><textarea class="textarea announcement-input" id="announcement-body" name="body" maxlength="2000" required placeholder="Write an announcement for your band…"></textarea><div class="announcement-compose-foot"><span class="muted-note">Visible to members of ${esc(state.band.name)} only</span><button class="btn btn-primary" type="submit">Post announcement</button></div></form><div class="announcement-feed" aria-live="polite">${announcements}</div></section><section class="dashboard-grid" aria-label="Band dashboard"><article class="dash-card feature"><div class="dash-title">Next rehearsal</div>${nextContent}</article><article class="dash-card"><div class="dash-title">On the setlist</div>${planned}</article><article class="dash-card"><div class="dash-title">Needs more practice</div>${practice}</article><article class="dash-card" style="grid-column:1/-1;min-height:auto"><div class="dash-title">Recent member updates</div>${updates}</article></section><section><div class="songs-section-head"><h2>Song library <span class="song-count">${state.songs.length} shown</span></h2><button class="btn btn-small" data-action="new-song">＋ Add song</button></div>${renderSongFilters()}${renderSongGrid()}</section></main>`;
}

function renderSongFilters(){
  const q=state.songsQuery;const allTags=[...new Set(state.songs.flatMap(s=>s.tags||[]))].sort();
  return `<div class="filter-bar"><label class="search-wrap"><span aria-hidden="true">⌕</span><input class="input" aria-label="Search songs by title or original artist" name="song-search" value="${esc(q.q||'')}" placeholder="Search title or original artist"></label><select class="select" aria-label="Filter by status" data-filter="status">${selectOptions([{value:'suggested',label:'Suggested'},{value:'planned',label:'Planned'},{value:'learning',label:'Learning'},{value:'practicing',label:'Practicing'},{value:'ready',label:'Performance ready'},{value:'archived',label:'Archived'}],q.status||'','All statuses')}</select><select class="select" aria-label="Filter by singer" data-filter="singer">${memberOptions(q.singer||'','All singers')}</select><select class="select" aria-label="Filter by pianist" data-filter="pianist">${memberOptions(q.pianist||'','All pianists')}</select><select class="select" aria-label="Filter by priority" data-filter="priority">${selectOptions([1,2,3,4,5].map(v=>({value:v,label:`Priority ${v}`})),q.priority||'','All priorities')}</select><select class="select" aria-label="Filter by tag" data-filter="tag">${selectOptions(allTags.map(v=>({value:v,label:v})),q.tag||'','All tags')}</select><select class="select" aria-label="Sort songs" data-filter="sort">${selectOptions([{value:'priority',label:'Priority'},{value:'title',label:'Title'},{value:'added',label:'Date added'},{value:'practiced',label:'Last practiced'}],q.sort||'priority','Sort by')}</select></div>`;
}

function renderSongGrid(){
  if(!state.songs.length)return emptyState('♫','No songs found','Add your first song or adjust the search and filters.','<button class="btn btn-primary" data-action="new-song">Add a song</button>');
  return `<div class="song-grid">${state.songs.map(song=>`<article class="song-card" data-action="song-detail" data-id="${song.id}" tabindex="0" role="button" aria-label="Open ${esc(song.title)} by ${esc(song.artist)}"><div class="song-card-top"><div><h3>${esc(song.title)}</h3><div class="artist">${esc(song.artist)}</div></div>${statusPill(song.status)}</div><div class="song-card-meta"><span class="meta-item">${song.key_name?`Key ${esc(song.key_name)}`:'Key not set'}</span>${song.bpm?`<span class="meta-item">♩ ${song.bpm} BPM</span>`:''}${song.duration_minutes?`<span class="meta-item">◷ ${durationText(song.duration_minutes)}</span>`:''}${priorityDots(song.priority)}</div><div class="muted-note">${song.singers.length?`Vocals: ${song.singers.map(x=>esc(x.display_name)).join(', ')}`:'No singer assigned'}${song.pianist?` · Piano: ${esc(song.pianist.display_name)}`:''}</div>${song.tags.length?`<div class="song-tags">${song.tags.slice(0,4).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}${song.tags.length>4?`<span class="tag">+${song.tags.length-4}</span>`:''}</div>`:''}<div class="song-card-foot"><span>Edited by ${esc(song.updated_by_member?.display_name||'a member')} · ${esc(fmtInstant(song.updated_at,{month:'short',day:'numeric'}))}</span><span>▲ ${song.votes}</span></div><div class="song-card-actions"><button data-action="song-vote" data-id="${song.id}">${song.voted_by_me?'✓ Voted':'↑ Vote'}</button><button data-action="song-add-next" data-id="${song.id}">＋ Next rehearsal</button></div></article>`).join('')}</div>`;
}

function renderPracticePage(){
  const tabs=[['availability','Member availability'],['common','Common free times'],['rehearsals','Scheduled rehearsals'],['locations','Practice locations']];
  const content=state.practice==='availability'?renderAvailability():state.practice==='common'?renderCommon():state.practice==='rehearsals'?renderRehearsals():renderLocations();
  return `<main class="page-wrap"><div class="page-heading"><div><span class="eyebrow">Practice & availability</span><h1>Make time for the music.</h1><p>Plan together in ${esc(state.band.timezone)}. Availability changes never move a scheduled rehearsal automatically.</p></div><div class="actions">${state.practice==='availability'?'<button class="btn btn-primary" data-action="new-availability">＋ Add availability</button>':''}${state.practice==='rehearsals'?'<button class="btn btn-primary" data-action="new-rehearsal">＋ Plan rehearsal</button>':''}${state.practice==='locations'?'<button class="btn btn-primary" data-action="new-location">＋ Add location</button>':''}</div></div><nav class="subnav" aria-label="Practice sections">${tabs.map(([id,label])=>`<button class="${state.practice===id?'active':''}" data-practice="${id}">${label}</button>`).join('')}</nav>${content}</main>`;
}

function renderAvailability(){
  const from=state.weekStart||mondayOf(localDateString());const days=Array.from({length:7},(_,i)=>addDays(from,i));
  const all=state.availability||[];
  return `<section class="panel"><div class="week-head"><div><h2>Your band’s week</h2><div class="muted-note">Member names and colors identify each submitted period.</div></div><div class="actions"><button class="icon-btn" aria-label="Previous week" data-action="week-prev">‹</button><span class="muted-note">${esc(fmtDate(from,{month:'short',day:'numeric'}))} – ${esc(fmtDate(days[6],{month:'short',day:'numeric',year:'numeric'}))}</span><button class="icon-btn" aria-label="Next week" data-action="week-next">›</button></div></div><div class="warning-box">No entry means <strong>not submitted</strong>; it does not mean a member is free. Add more than one period on a day by submitting another entry.</div><div class="calendar-wrap"><div class="week-grid">${days.map(day=>{const entries=all.filter(e=>e.date===day);return `<div class="day-column"><div class="day-name">${esc(fmtDate(day,{weekday:'short'}))}</div><div class="day-date">${esc(fmtDate(day,{month:'short',day:'numeric'}))}</div>${entries.length?entries.map(e=>`<div class="availability-item ${e.is_mine?'mine':''} ${e.kind==='unavailable'?'unavailable':''}" style="--member-color:${esc(e.color)}"><strong>${esc(e.display_name)}${e.is_mine?' · You':''}</strong><span class="small-time">${e.kind==='unavailable'?'Unavailable all day':`${esc(fmtTime(e.start_time))}–${esc(fmtTime(e.end_time))}`}${e.recurrence==='weekly'?' · Weekly':''}</span>${e.note?`<div>${esc(e.note)}</div>`:''}<div class="song-card-actions">${e.is_mine||state.member.role==='admin'?`<button data-action="edit-availability" data-id="${e.id}" data-date="${e.date}" aria-label="Edit ${esc(e.display_name)} availability">Edit</button>`:''}${e.recurrence==='weekly'&&(e.is_mine||state.member.role==='admin')?`<button data-action="skip-availability" data-id="${e.id}" data-date="${e.date}">Skip date</button>`:''}${e.is_mine||state.member.role==='admin'?`<button data-action="delete-availability" data-id="${e.id}" data-version="${e.version}">Remove</button>`:''}</div></div>`).join(''):'<div class="muted-note" style="grid-column:1/-1">No submitted times</div>'}</div>`}).join('')}</div></div></section><div class="muted-note" style="margin-top:12px">Weekly periods follow ${esc(state.band.timezone)} and account for daylight-saving changes. This week shows local wall-clock times.</div>`;
}

function renderCommon(){
  const selected=state.overlap?.required_member_ids||state.members.map(m=>m.id);
  const slots=state.overlap?.slots||[];
  return `<section class="panel"><h2>Find a rehearsal window</h2><p class="panel-sub">We compare actual overlapping start and end times. Full-band times rank first; if there are none, alternatives show who can and cannot make each slot.</p><form id="overlap-form"><div class="common-controls"><div class="field"><label for="range-from">Date range</label><div class="inline-fields"><input id="range-from" class="input" type="date" name="from" value="${esc(localDateString())}" required><span class="muted-note">to</span><input class="input" type="date" name="to" value="${esc(addDays(localDateString(),28))}" required></div></div><div class="field"><label for="min-duration">Minimum time</label><select id="min-duration" class="select" name="min_minutes">${selectOptions([{value:60,label:'1 hour'},{value:90,label:'1.5 hours'},{value:120,label:'2 hours'},{value:150,label:'2.5 hours'},{value:180,label:'3 hours'}],120,'')}</select></div><button class="btn btn-primary" type="submit">Find times</button></div><div class="field-label" style="margin-top:17px">Required members <span class="muted-note">(defaults to the whole band)</span></div>${memberChecks('required_member_ids',selected)}</form>${state.overlap?`<div class="slot-list">${slots.length?slots.map(slot=>renderSlot(slot)).join(''):emptyState('◷','No overlapping windows yet','Submit member availability for the selected dates, then search again.')}</div>`:`<div class="empty-state" style="margin-top:18px"><div class="empty-icon">◷</div><h3>Find a time that works</h3><p>Choose a date range and minimum duration to compare submitted availability.</p></div>`}</section>`;
}
function renderSlot(slot){
  const full=slot.available_count===state.overlap.required_member_ids.length&&slot.available_count>0;
  const states=state.members.filter(m=>slot.member_status[String(m.id)]).map(m=>{const s=slot.member_status[String(m.id)];const label=s==='not_submitted'?'Not submitted':s==='available'?'Available':'Unavailable';return `<span class="person-state" title="${label}"><i class="dot" style="--state-color:${esc(m.color)}"></i>${esc(m.display_name)}: ${label}</span>`}).join('');
  return `<article class="slot-card ${full?'full':''}"><div><h3>${esc(fmtDate(slot.date,{weekday:'long',month:'short',day:'numeric'}))} · ${esc(fmtTime(slot.start_time))}–${esc(fmtTime(slot.end_time))}</h3><div class="slot-time">${slot.available_count} of ${state.overlap.required_member_ids.length} selected members · ${durationText(slot.duration_minutes)} ${full?'· Full overlap':''}</div><div class="slot-status">${states}</div></div><button class="btn btn-small ${full?'btn-primary':''}" data-action="propose-slot" data-date="${esc(slot.date)}" data-start="${esc(slot.start_time)}" data-end="${esc(slot.end_time)}" data-members="${esc(JSON.stringify(state.overlap.required_member_ids))}">Propose rehearsal</button></article>`;
}

function renderRehearsals(){
  const items=state.rehearsals||[];
  if(!items.length)return emptyState('◷','No rehearsals scheduled','Create a proposed rehearsal or find a time that works for everyone.','<button class="btn btn-primary" data-action="new-rehearsal">Plan a rehearsal</button>');
  return `<div class="rehearsal-list">${items.map(r=>{const local=new Date(r.start_utc);return `<article class="rehearsal-card"><div class="date-block"><strong>${esc(new Intl.DateTimeFormat('en-CA',{timeZone:state.band.timezone,day:'2-digit'}).format(local))}</strong><span>${esc(new Intl.DateTimeFormat('en-CA',{timeZone:state.band.timezone,month:'short'}).format(local))}</span></div><div><h3>${esc(r.title)}${r.event_type==='performance'?' · Performance':''} ${r.status==='proposed'?'<span class="status status-suggested">Proposed</span>':`<span class="status status-${esc(r.status)}">${esc(r.status)}</span>`}</h3><div class="rehearsal-meta">${esc(fmtInstant(r.start_utc,{weekday:'long',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))} · ${durationText(r.duration_minutes)}<br><strong>${esc(r.location_name_snapshot||'Location to be decided')}</strong>${r.address_snapshot?` · ${esc(r.address_snapshot)}`:''} · ${money(r.total_cost_cad)}</div></div><div class="rehearsal-actions"><button class="btn btn-small" data-action="rehearsal-detail" data-id="${r.id}">Open plan</button><button class="btn btn-small" data-action="download-calendar" data-id="${r.id}" aria-label="Download ${esc(r.title)} calendar event">Add to calendar</button></div></article>`}).join('')}</div>`;
}

function renderLocations(){
  if(!state.locations.length)return emptyState('⌖','No practice locations saved','Save a venue once to reuse its address, equipment, and rates in rehearsal plans.','<button class="btn btn-primary" data-action="new-location">Add location</button>');
  return `<div class="location-grid">${state.locations.map(l=>`<article class="location-card"><h3>${esc(l.name)}</h3><p>${esc(l.address||'Address not set')}${l.map_url?` · <a href="${esc(l.map_url)}" target="_blank" rel="noopener">Map</a>`:''}</p>${l.contact||l.booking_link?`<p>${l.contact?`Contact: ${esc(l.contact)}`:''}${l.contact&&l.booking_link?' · ':''}${l.booking_link?`<a href="${esc(l.booking_link)}" target="_blank" rel="noopener">Booking ↗</a>`:''}</p>`:''}${l.equipment?.length?`<div class="equipment">${l.equipment.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div>`:''}<div class="location-rate">${l.hourly_rate!=null?`${money(l.hourly_rate)} / hour`:l.flat_cost!=null?`${money(l.flat_cost)} flat`:'Rate not set'}</div>${l.notes?`<p style="margin-top:9px">${esc(l.notes)}</p>`:''}<div class="location-row-actions"><button class="btn btn-small" data-action="edit-location" data-id="${l.id}">Edit</button><button class="btn btn-small btn-danger" data-action="delete-location" data-id="${l.id}" data-version="${l.version}">Delete</button></div></article>`).join('')}</div>`;
}

async function refreshPractice(){
  if(state.practice==='availability')await loadAvailability();
  if(state.practice==='common'){if(!state.availability.length)await loadAvailability()}
  if(state.practice==='rehearsals')await loadRehearsals();
  if(state.practice==='locations')await loadLocations();
  // Keep the current page responsive when the data arrives after the shell.
  const active=app.querySelector('.page-wrap');if(active&&state.tab==='practice')renderAppNoRefresh();
}
function renderAppNoRefresh(){const page=renderPracticePage();const current=app.querySelector('.page-wrap');if(current)current.outerHTML=page;}

function songForm(song=null){
  const edit=!!song;const tags=(song?.tags||[]).join(', ');const links=(song?.links||[]).map(x=>`${x.label} | ${x.url}`).join('\n');
  const perf=(song?.performed_dates||[]).join('\n');
  const upcoming=state.dashboard?.next_rehearsal;
  const addToRehearsal=upcoming?`<label class="check-pill"><input type="checkbox" name="add_to_next" value="1"> Add to next rehearsal: ${esc(upcoming.title)}</label>`:'';
  showModal(edit?'Edit song':'Add a song',edit?`Updated by ${song.updated_by_member?.display_name||'a member'} · ${fmtInstant(song.updated_at,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}`:'Shared with everyone in the band',`<form id="song-form" data-song-id="${edit?song.id:''}" data-version="${edit?song.version:''}"><div class="form-grid"><div class="field"><label for="song-title">Song title *</label><input id="song-title" class="input" name="title" required maxlength="160" value="${esc(song?.title||'')}" placeholder="Song title"></div><div class="field"><label for="song-artist">Original artist *</label><input id="song-artist" class="input" name="artist" required maxlength="160" value="${esc(song?.artist||'')}" placeholder="Original artist"></div><div class="field"><label for="song-status">Current status</label><select id="song-status" class="select" name="status">${selectOptions(Object.entries(STATUS).map(([value,label])=>({value,label})),song?.status||'suggested','')}</select></div><div class="field"><label for="song-key">Our performance key</label><input id="song-key" class="input" name="key_name" maxlength="20" value="${esc(song?.key_name||'')}" placeholder="e.g. G major"></div><div class="field"><label for="song-bpm">Tempo / BPM</label><input id="song-bpm" class="input" type="number" name="bpm" min="20" max="400" value="${esc(song?.bpm??'')}" placeholder="e.g. 112"></div><div class="field"><label for="song-duration">Approx. duration (minutes)</label><input id="song-duration" class="input" type="number" name="duration_minutes" min="1" max="300" value="${esc(song?.duration_minutes??'')}" placeholder="e.g. 4"></div><div class="field"><label for="song-difficulty">Difficulty (1–5)</label><select id="song-difficulty" class="select" name="difficulty">${selectOptions([1,2,3,4,5].map(v=>({value:v,label:`${v} / 5`})),song?.difficulty||'','Not rated')}</select></div><div class="field"><label for="song-priority">Priority (1–5)</label><select id="song-priority" class="select" name="priority">${selectOptions([1,2,3,4,5].map(v=>({value:v,label:`${v} / 5`})),song?.priority||3,'')}</select></div><div class="field full"><span class="field-label">Assigned singers</span>${memberChecks('singer_ids',song?.singer_ids||[])}</div><div class="field"><label for="song-pianist">Assigned pianist</label><select id="song-pianist" class="select" name="pianist_id">${memberOptions(song?.pianist_id||'','No pianist assigned')}</select></div><div class="field"><label for="song-tags">Tags</label><input id="song-tags" class="input" name="tags" value="${esc(tags)}" placeholder="genre, acoustic, energetic"></div><div class="field full"><label class="checkbox-row"><input type="checkbox" name="performed_live" value="1" ${song?.performed_live?'checked':''}> We have performed this song live</label></div><div class="field full"><label for="performance-dates">Performance dates <span class="help">Optional, one YYYY-MM-DD date per line</span></label><textarea id="performance-dates" class="textarea" name="performed_dates" placeholder="2026-06-14">${esc(perf)}</textarea></div><div class="field full"><label for="song-links">Reference links <span class="help">One per line: label | https://…</span></label><textarea id="song-links" class="textarea" name="links" placeholder="Original recording | https://…\nChord chart | https://…">${esc(links)}</textarea></div><div class="field full"><label for="arrangement-notes">Arrangement notes</label><textarea id="arrangement-notes" class="textarea" name="arrangement_notes" placeholder="Intro, ending, solos, transitions, changes from the original…">${esc(song?.arrangement_notes||'')}</textarea></div><div class="field full"><label for="practice-notes">Practice notes and next goals</label><textarea id="practice-notes" class="textarea" name="practice_notes" placeholder="What needs work, difficult passages, goals for next rehearsal…">${esc(song?.practice_notes||'')}</textarea></div>${!edit&&upcoming?`<div class="field full">${addToRehearsal}</div>`:''}</div><div id="duplicate-warning" class="warning-box" hidden></div><div id="form-error" class="error-text" hidden></div><button type="button" id="reload-conflict" class="btn btn-small" data-action="reload-conflict-song" hidden>Reload latest song</button><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${edit?'Save song':'Add to song library'}</button></div></form>`);
}

async function openSongDetail(id){
  try{const song=await api(`/api/songs/${id}`);state.openSong=song;const comments=song.comments||[];const history=song.practice_history||[];
    showModal('',`${esc(song.artist)} · Edited by ${esc(song.updated_by_member?.display_name||'a member')} ${esc(fmtInstant(song.updated_at,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))}`,`<div class="rehearsal-detail-top"><div><h2 class="detail-title">${esc(song.title)}</h2><p class="detail-subtitle">${esc(song.artist)} · ${statusPill(song.status)}</p></div><div class="actions"><button class="btn btn-small" data-action="edit-song" data-id="${song.id}">Edit song</button><button class="icon-btn" aria-label="Close dialog" data-action="close-modal">×</button></div></div><div class="detail-layout"><div class="detail-box"><div class="label">Song setup</div><p>Key: ${esc(song.key_name||'Not set')} · ${song.bpm?`${song.bpm} BPM`:'Tempo not set'} · ${song.duration_minutes?durationText(song.duration_minutes):'Duration not set'}<br>Difficulty: ${song.difficulty||'Not rated'} / 5 · Priority: ${song.priority} / 5<br>Live performance: ${song.performed_live?'Yes':'Not yet'}${song.performed_dates.length?` · ${song.performed_dates.map(d=>esc(fmtDate(d,{month:'short',day:'numeric',year:'numeric'}))).join(', ')}`:''}</p></div><div class="detail-box"><div class="label">Assignments</div><p>Singers: ${song.singers.length?song.singers.map(m=>esc(m.display_name)).join(', '):'Unassigned'}<br>Pianist: ${esc(song.pianist?.display_name||'Unassigned')}</p></div><div class="detail-box"><div class="label">Arrangement</div><p>${esc(song.arrangement_notes||'No arrangement notes yet.')}</p></div><div class="detail-box"><div class="label">Practice goals</div><p>${esc(song.practice_notes||'No practice notes yet.')}</p></div></div>${song.tags.length?`<div class="song-tags">${song.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`:''}${song.links.length?`<div class="modal-section"><h3>References</h3><div class="kv-list">${song.links.map(l=>`<div class="kv-row"><span class="k">${esc(l.label)}</span><a href="${esc(l.url)}" target="_blank" rel="noopener">Open link ↗</a></div>`).join('')}</div></div>`:''}<div class="modal-section"><div class="actions" style="justify-content:space-between"><h3>Song suggestion votes · ${song.votes}</h3><button class="btn btn-small" data-action="song-vote" data-id="${song.id}">${song.voted_by_me?'✓ Remove my vote':'↑ Vote for this song'}</button></div></div><div class="modal-section"><h3>Practice history</h3>${history.length?`<div class="kv-list">${history.map(h=>`<div class="kv-row"><span class="k">${esc(fmtInstant(h.start_utc,{month:'short',day:'numeric',year:'numeric'}))}</span><span><strong>${esc(h.title)}</strong>${h.notes?` · ${esc(h.notes)}`:''}</span></div>`).join('')}</div>`:'<p class="muted-note">This song has not been added to a rehearsal yet.</p>'}</div><div class="modal-section"><h3>Discussion</h3><div class="comment-list">${comments.length?comments.map(c=>`<div class="comment">${avatar({display_name:c.display_name,color:c.color})}<div class="comment-body"><strong>${esc(c.display_name)}</strong> ${esc(c.body)}<time>${esc(fmtInstant(c.created_at,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))}</time></div></div>`).join(''):'<p class="muted-note">No comments yet. Add a note for the band.</p>'}</div><form id="comment-form" data-song-id="${song.id}" class="inline-fields" style="margin-top:12px"><input class="input" name="body" maxlength="2000" required placeholder="Add a comment…" aria-label="Add a comment"><button class="btn btn-primary btn-small" type="submit">Post</button></form></div><div class="modal-actions"><button class="btn btn-danger" data-action="delete-song" data-id="${song.id}" data-version="${song.version}">Delete song</button><button class="btn" data-action="close-modal">Done</button></div>`);
  }catch(e){toast(e.message,true)}
}

function openAvailabilityForm(entry=null, day=null){
  const edit=!!entry;const dateValue=day||entry?.start_date||localDateString();const startDate=entry?.start_date||dateValue;
  showModal(edit?'Edit availability':'Add availability',`Times are interpreted in ${state.band.timezone}. You can submit multiple periods on one day.`,
  `<form id="availability-form" data-id="${entry?.id||''}" data-version="${entry?.version||''}"><div class="form-grid"><div class="field"><label for="avail-date">Date</label><input id="avail-date" class="input" type="date" name="start_date" required value="${esc(startDate)}"></div><div class="field"><label for="avail-recurrence">Repeat</label><select id="avail-recurrence" class="select" name="recurrence"><option value="none" ${entry?.recurrence!=='weekly'?'selected':''}>One time</option><option value="weekly" ${entry?.recurrence==='weekly'?'selected':''}>Weekly</option></select></div><div class="field weekly-until" ${entry?.recurrence==='weekly'?'':'hidden'}><label for="avail-until">Repeat until <span class="help">Optional</span></label><input id="avail-until" class="input" type="date" name="until_date" value="${esc(entry?.until_date||'')}"></div><div class="field full"><label class="checkbox-row"><input type="checkbox" name="unavailable" value="1" ${entry?.kind==='unavailable'?'checked':''}> Mark this date as unavailable all day</label></div><div class="field availability-time"><label for="avail-start">Available from</label><input id="avail-start" class="input" type="time" name="start_time" required value="${esc(entry?.start_time==='24:00'?'':entry?.start_time||'18:00')}"></div><div class="field availability-time"><label for="avail-end">Available until</label><input id="avail-end" class="input" type="time" name="end_time" required value="${esc(entry?.end_time==='24:00'?'':entry?.end_time||'20:00')}"></div><div class="field full"><label for="avail-note">Optional note</label><input id="avail-note" class="input" name="note" maxlength="500" value="${esc(entry?.note||'')}" placeholder="Can arrive after work, bringing a keyboard…"></div></div>${edit&&entry.recurrence==='weekly'&&entry.exceptions?.length?`<div class="modal-section"><h3>Skipped dates</h3><div class="kv-list">${entry.exceptions.map(ex=>`<div class="kv-row"><span class="k">${esc(fmtDate(ex,{month:'short',day:'numeric',year:'numeric'}))}</span><button type="button" class="btn btn-small" data-action="unskip-availability" data-id="${entry.id}" data-date="${esc(ex)}">Restore date</button></div>`).join('')}</div></div>`:''}<div id="form-error" class="error-text" hidden></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">${edit?'Save changes':'Submit availability'}</button></div></form>`);
  toggleAvailabilityFields();
}

function rehearsalForm(rehearsal=null, prefill=null){
  const edit=!!rehearsal;const r=rehearsal||{};const dateVal=prefill?.date|| (r.start_utc?dateInZone(r.start_utc):localDateString());
  const startVal=prefill?.start|| (r.start_utc?timeInZone(r.start_utc):'18:00');const endVal=prefill?.end||(r.end_utc?timeInZone(r.end_utc):'20:00');
  const invited=edit?(r.invited_ids||[]):(prefill?.members||state.members.map(m=>m.id));const splitIds=r.split_member_ids||[];
  const locOpts=state.locations.map(l=>({value:l.id,label:`${l.name}${l.address?` · ${l.address}`:''}`}));
  showModal(edit?'Edit rehearsal':'Plan a rehearsal',`Times use ${state.band.timezone}. Cost stays recorded if a saved location’s rate changes later.`,
  `<form id="rehearsal-form" data-id="${r.id||''}" data-version="${r.version||''}"><div class="form-grid"><div class="field full"><label for="rehearsal-title">Title *</label><input id="rehearsal-title" class="input" name="title" required maxlength="140" value="${esc(r.title||'Band rehearsal')}" placeholder="Band rehearsal"></div><div class="field"><label for="rehearsal-date">Date</label><input id="rehearsal-date" class="input" type="date" name="date" required value="${esc(dateVal)}"></div><div class="field"><label for="rehearsal-type">Type</label><select id="rehearsal-type" class="select" name="event_type">${selectOptions([{value:'rehearsal',label:'Rehearsal'},{value:'performance',label:'Performance'}],r.event_type||'rehearsal','')}</select></div><div class="field"><label for="rehearsal-status">Status</label><select id="rehearsal-status" class="select" name="status">${selectOptions([{value:'proposed',label:'Proposed'},{value:'confirmed',label:'Confirmed'},{value:'completed',label:'Completed'},{value:'cancelled',label:'Cancelled'}],r.status||'proposed','')}</select></div><div class="field"><label for="rehearsal-start">Start time</label><input id="rehearsal-start" class="input" type="time" name="start_time" required value="${esc(startVal)}"></div><div class="field"><label for="rehearsal-end">End time</label><input id="rehearsal-end" class="input" type="time" name="end_time" required value="${esc(endVal)}"></div><div class="field full"><label for="rehearsal-location">Saved practice location</label><select id="rehearsal-location" class="select" name="location_id">${selectOptions(locOpts,r.location_id||'','Choose later or enter a one-off location')}</select></div><div class="field"><label for="rehearsal-location-name">Location name</label><input id="rehearsal-location-name" class="input" name="location_name" value="${esc(r.location_name_snapshot||'')}" placeholder="Studio, home, park…"></div><div class="field"><label for="rehearsal-address">Full address</label><input id="rehearsal-address" class="input" name="address" value="${esc(r.address_snapshot||'')}" placeholder="Street address"></div><div class="field"><label for="room-number">Room number</label><input id="room-number" class="input" name="room_number" value="${esc(r.room_number||'')}" placeholder="Room 204"></div><div class="field"><label for="booking-reference">Booking reference</label><input id="booking-reference" class="input" name="booking_reference" value="${esc(r.booking_reference||'')}" placeholder="Confirmation number"></div><div class="field"><label for="booking-link">Booking link</label><input id="booking-link" class="input" name="booking_link" value="${esc(r.booking_link||'')}" placeholder="https://…"></div><div class="field"><label for="manual-cost">Total cost (CAD)</label><input id="manual-cost" class="input" name="total_cost_cad" type="number" min="0" max="100000" step="0.01" value="" placeholder="${edit?esc(Number(r.total_cost_cad||0).toFixed(2)):'Auto from location'}"><span class="help">${edit?'Leave blank to keep the recorded cost. Enter an amount for a manual override.':'Leave blank to estimate from the saved location.'}</span></div>${edit?`<div class="field full"><label class="checkbox-row"><input type="checkbox" name="recalculate_cost" value="1"> Recalculate from the saved location rate</label><span class="help">Use the venue’s current saved rate for this rehearsal.</span></div>`:''}<div class="field"><label for="cost-mode">Cost split</label><select id="cost-mode" class="select" name="split_mode">${selectOptions([{value:'attending',label:'Attending members'},{value:'active',label:'All active members'},{value:'selected',label:'Selected members'}],r.split_mode||'attending','')}</select></div><div class="field full manual-split" ${r.split_mode==='selected'?'':'hidden'}><span class="field-label">Members in manual split</span>${memberChecks('split_member_ids',splitIds)}</div><div class="field full"><span class="field-label">Invited members</span>${memberChecks('invited_ids',invited)}</div><div class="field full"><label for="rehearsal-goals">Rehearsal goals</label><textarea id="rehearsal-goals" class="textarea" name="goals" placeholder="Songs to focus on, goals for the session…">${esc(r.goals||'')}</textarea></div><div class="field full"><label for="rehearsal-notes">Notes</label><textarea id="rehearsal-notes" class="textarea" name="notes" placeholder="Anything to bring, access notes…">${esc(r.notes||'')}</textarea></div>${edit?`<div class="field full"><label for="rehearsal-summary">Post-rehearsal summary</label><textarea id="rehearsal-summary" class="textarea" name="summary" placeholder="What went well, what to pick up next time…">${esc(r.summary||'')}</textarea></div>`:''}</div><div id="cost-estimate" class="muted-note" style="margin-top:10px"></div><div id="form-error" class="error-text" hidden></div><button type="button" id="reload-conflict" class="btn btn-small" data-action="reload-conflict-rehearsal" hidden>Reload latest rehearsal</button><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${edit?'Save rehearsal':'Create proposed rehearsal'}</button></div></form>`);
  updateCostEstimate();
}
function timeInZone(iso){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:state.band.timezone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(iso));const v=Object.fromEntries(parts.map(p=>[p.type,p.value]));return `${v.hour}:${v.minute}`;}
function dateInZone(iso){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:state.band.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(iso));const v=Object.fromEntries(parts.map(p=>[p.type,p.value]));return `${v.year}-${v.month}-${v.day}`;}

function announcementForm(announcement){
  showModal('Edit announcement',`Posted by ${announcement.display_name} · Updated ${fmtInstant(announcement.updated_at,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}`,`<form id="announcement-edit-form" data-id="${announcement.id}" data-version="${announcement.version}"><div class="field"><label for="announcement-edit-body">Announcement</label><textarea class="textarea" id="announcement-edit-body" name="body" required maxlength="2000">${esc(announcement.body)}</textarea></div><div id="form-error" class="error-text" hidden></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">Save announcement</button></div></form>`);
}

function icsText(value=''){return String(value??'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');}
function icsFold(line){const encoder=new TextEncoder();let output='',part='',bytes=0;for(const character of line){const size=encoder.encode(character).length;if(bytes+size>73){output+=part+'\r\n ';part='';bytes=1}part+=character;bytes+=size}return output+part;}
function downloadCalendar(rehearsal){
  const stamp=iso=>new Date(iso).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');
  const summary=`${rehearsal.event_type==='performance'?'Performance: ':''}${rehearsal.title}`;
  const place=[rehearsal.location_name_snapshot,rehearsal.address_snapshot,rehearsal.room_number?`Room ${rehearsal.room_number}`:''].filter(Boolean).join(', ');
  const description=[rehearsal.goals?`Goals: ${rehearsal.goals}`:'',rehearsal.notes?`Notes: ${rehearsal.notes}`:'',rehearsal.booking_link?`Booking: ${rehearsal.booking_link}`:''].filter(Boolean).join('\n');
  const status=rehearsal.status==='proposed'?'TENTATIVE':rehearsal.status==='cancelled'?'CANCELLED':'CONFIRMED';
  const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Bandroom//Rehearsal Calendar//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH','BEGIN:VEVENT',`UID:bandroom-${rehearsal.band_id||'band'}-rehearsal-${rehearsal.id}@bandroom`,`DTSTAMP:${stamp(new Date().toISOString())}`,`DTSTART:${stamp(rehearsal.start_utc)}`,`DTEND:${stamp(rehearsal.end_utc)}`,`SUMMARY:${icsText(summary)}`,`DESCRIPTION:${icsText(description)}`,`LOCATION:${icsText(place)}`,`STATUS:${status}`,'END:VEVENT','END:VCALENDAR'];
  const blob=new Blob([lines.map(icsFold).join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');const slug=String(rehearsal.title||'rehearsal').normalize('NFKD').replace(/[^\w-]+/g,'-').replace(/^-|-$/g,'').toLowerCase()||`rehearsal-${rehearsal.id}`;anchor.href=url;anchor.download=`bandroom-${slug}.ics`;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

function locationForm(location=null){const edit=!!location;showModal(edit?'Edit practice location':'Save practice location','Reusable details are private to this band.',`<form id="location-form" data-id="${location?.id||''}" data-version="${location?.version||''}"><div class="form-grid"><div class="field"><label for="loc-name">Venue name *</label><input id="loc-name" class="input" name="name" required maxlength="120" value="${esc(location?.name||'')}" placeholder="Studio name"></div><div class="field"><label for="loc-address">Address</label><input id="loc-address" class="input" name="address" maxlength="400" value="${esc(location?.address||'')}" placeholder="Full address"></div><div class="field"><label for="loc-map">Map link</label><input id="loc-map" class="input" name="map_url" value="${esc(location?.map_url||'')}" placeholder="https://maps…"></div><div class="field"><label for="loc-booking">Booking link</label><input id="loc-booking" class="input" name="booking_link" value="${esc(location?.booking_link||'')}" placeholder="https://…"></div><div class="field"><label for="loc-hourly">Hourly rate (CAD)</label><input id="loc-hourly" class="input" name="hourly_rate" type="number" min="0" max="100000" step="0.01" value="${esc(location?.hourly_rate??'')}"></div><div class="field"><label for="loc-flat">Flat booking cost (CAD)</label><input id="loc-flat" class="input" name="flat_cost" type="number" min="0" max="100000" step="0.01" value="${esc(location?.flat_cost??'')}"></div><div class="field"><label for="loc-contact">Contact details</label><input id="loc-contact" class="input" name="contact" value="${esc(location?.contact||'')}" placeholder="Email or phone"></div><div class="field"><label for="loc-equipment">Equipment available</label><input id="loc-equipment" class="input" name="equipment" value="${esc((location?.equipment||[]).join(', '))}" placeholder="Drums, piano, amps, mics"></div><div class="field full"><label for="loc-notes">Access, parking, and room rules</label><textarea id="loc-notes" class="textarea" name="notes" maxlength="2000" placeholder="Parking, load-in, room rules…">${esc(location?.notes||'')}</textarea></div></div><div id="form-error" class="error-text" hidden></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">${edit?'Save location':'Save location'}</button></div></form>`);}

function openRehearsalDetail(id){
  api(`/api/rehearsals/${id}`).then(r=>{state.openRehearsal=r;
    const conflicts=(r.availability_conflict_ids||[]).map(id=>state.members.find(m=>m.id===id)).filter(Boolean);
    const localStart=fmtInstant(r.start_utc,{weekday:'long',month:'long',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});const localEnd=fmtInstant(r.end_utc,{hour:'numeric',minute:'2-digit'});
    showModal('',`${esc(r.title)} · ${esc(localStart)}–${esc(localEnd)} (${esc(r.timezone)})`,
    `<div class="rehearsal-detail-top"><div><h2 class="detail-title">${esc(r.title)}</h2><p class="detail-subtitle"><span class="status status-${r.status==='proposed'?'suggested':esc(r.status)}">${esc(r.status)}</span> · ${r.event_type==='performance'?'Performance':'Rehearsal'} · Organized by ${esc(r.organizer.display_name)}</p></div><div class="actions"><button class="btn btn-small" data-action="edit-rehearsal" data-id="${r.id}">Edit plan</button><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">×</button></div></div>${conflicts.length?`<div class="warning-box"><strong>Availability conflict:</strong> ${conflicts.map(m=>esc(m.display_name)).join(', ')} submitted availability that conflicts with this scheduled time. The schedule has not moved. Members can update their response or availability.</div>`:''}<div class="modal-section"><div class="kv-list"><div class="kv-row"><span class="k">When</span><span>${esc(localStart)}–${esc(localEnd)} · ${durationText(r.duration_minutes)} · ${esc(r.timezone)}</span></div><div class="kv-row"><span class="k">Location</span><span>${esc(r.location_name_snapshot||'To be decided')}${r.room_number?` · ${esc(r.room_number)}`:''}<br>${esc(r.address_snapshot||'Address not set')}${r.booking_link?` · <a href="${esc(r.booking_link)}" target="_blank" rel="noopener">Booking link ↗</a>`:''}${r.booking_reference?`<br>Ref: ${esc(r.booking_reference)}`:''}</span></div><div class="kv-row"><span class="k">Goals</span><span>${esc(r.goals||'No goals added')}</span></div><div class="kv-row"><span class="k">Notes</span><span>${esc(r.notes||'No notes')}</span></div>${r.summary?`<div class="kv-row"><span class="k">Summary</span><span>${esc(r.summary)}</span></div>`:''}<div class="kv-row"><span class="k">Last edited</span><span>${esc(r.updated_by_member?.display_name||'A band member')} · ${esc(fmtInstant(r.updated_at,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))}</span></div></div></div><div class="modal-section"><h3>Attendance</h3><div class="kv-list">${r.attendance.map(a=>`<div class="kv-row"><span class="k">${esc(a.display_name)}</span><span class="inline-fields">${a.member_id===state.member.id||state.member.role==='admin'?`<select class="select status-select" data-response-member="${a.member_id}">${selectOptions(Object.entries(ATTENDANCE).map(([value,label])=>({value,label})),a.response,'')}</select><button class="btn btn-small" data-action="set-response" data-id="${r.id}" data-member="${a.member_id}">Save response</button>`:`${esc(ATTENDANCE[a.response]||a.response)}`}</span></div>`).join('')}</div></div><div class="modal-section"><div class="actions" style="justify-content:space-between"><h3>Setlist · ${r.songs.length} songs · ${durationText(r.songs.reduce((a,s)=>a+(s.duration_minutes||0),0))} estimated</h3></div>${r.songs.length?`<div class="setlist">${r.songs.map((s,i)=>`<div class="set-row"><span class="set-order">${i>0?`<button data-action="move-set-up" data-id="${r.id}" data-version="${r.version}" data-song="${s.song_id}" data-position="${i}" aria-label="Move ${esc(s.title)} up">↑</button>`:''}<span class="set-index">${String(i+1).padStart(2,'0')}</span>${i<r.songs.length-1?`<button data-action="move-set-down" data-id="${r.id}" data-version="${r.version}" data-song="${s.song_id}" data-position="${i+2}" aria-label="Move ${esc(s.title)} down">↓</button>`:''}</span><span><strong>${esc(s.title)}</strong> <span class="muted-note">${esc(s.artist)}${s.notes?` · ${esc(s.notes)}`:''}</span></span><button class="icon-btn" data-action="remove-set-song" data-id="${r.id}" data-version="${r.version}" data-song="${s.song_id}" aria-label="Remove ${esc(s.title)} from setlist">×</button></div>`).join('')}</div>`:'<p class="muted-note">No songs planned yet.</p>'}<form id="setlist-form" data-rehearsal="${r.id}" data-version="${r.version}" class="inline-fields" style="margin-top:11px"><select class="select" name="song_id" required>${selectOptions(state.songs.filter(s=>!r.songs.some(v=>v.song_id===s.id)).map(s=>({value:s.id,label:`${s.title} — ${s.artist}`})),'','Add a song')}</select><input class="input" name="notes" maxlength="1000" placeholder="Practice focus (optional)"><button class="btn btn-primary btn-small" type="submit">Add song</button></form></div><div class="modal-section"><h3>Room cost · ${money(r.total_cost_cad)} total</h3><p class="muted-note">Split: ${r.split_mode==='attending'?'attending members':r.split_mode==='active'?'all active members':'selected members'}${r.venue_paid_by?` · Venue paid by ${esc(r.venue_paid_by.display_name)}`:''}</p>${r.cost_shares.length?`<table class="share-table"><thead><tr><th>Member</th><th>Share</th><th>Reimbursement</th><th></th></tr></thead><tbody>${r.cost_shares.map(c=>`<tr><td>${esc(c.display_name)}</td><td>${money(c.amount_cad)}</td><td>${c.reimbursement_paid?'Paid':'Unpaid'}</td><td>${c.member_id===state.member.id||state.member.role==='admin'?`<button class="btn btn-small" data-action="toggle-paid" data-id="${r.id}" data-member="${c.member_id}" data-paid="${c.reimbursement_paid?'0':'1'}">Mark ${c.reimbursement_paid?'unpaid':'paid'}</button>`:'—'}</td></tr>`).join('')}</tbody></table>`:`<p class="muted-note">No members are included in this split yet. Attending members are added as they respond.</p>`}<div class="inline-fields" style="margin-top:12px"><label class="field" style="flex:1"><span class="field-label">Who paid the venue?</span><select class="select" id="venue-payer">${memberOptions(r.venue_paid_by_id||'','Not recorded')}</select></label><button class="btn btn-small" data-action="save-payer" data-id="${r.id}">Record venue payment</button></div></div><div class="modal-actions"><button class="btn btn-danger" data-action="delete-rehearsal" data-id="${r.id}" data-version="${r.version}">Delete rehearsal</button><button class="btn" data-action="close-modal">Done</button></div>`);
  }).catch(e=>toast(e.message,true));
}

function profileForm(){const m=state.member;showModal('My profile','Your role helps the band know who normally plays which part.',`<form id="profile-form"><div class="form-grid"><div class="field full"><label for="profile-name">Display name</label><input id="profile-name" class="input" name="display_name" required maxlength="80" value="${esc(m.display_name)}"></div><div class="field full"><span class="field-label">Band roles</span>${['drummer','guitarist','bassist','other'].map(role=>`<label class="check-pill"><input type="checkbox" name="roles" value="${role}" ${(m.roles||[]).includes(role)?'checked':''}> ${role[0].toUpperCase()+role.slice(1)}</label>`).join('')}</div><div class="field"><label for="profile-color">Calendar color</label><input id="profile-color" class="input" name="color" type="color" value="${esc(m.color||'#5c9d8b')}" style="padding:4px;height:42px"></div><div class="field"><label>Account</label><div class="input" style="background:#f6f8f5">${esc(m.email)} · ${esc(m.role)}</div></div></div><div id="form-error" class="error-text" hidden></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">Save profile</button></div></form>`);}
function inviteForm(){showModal('Invite a band member','Invite links work once and expire after seven days.',`<div class="empty-state" style="padding:22px"><div class="empty-icon">✉</div><h3>Bring someone into the band</h3><p>They will create an individual account and join this private band workspace.</p><button class="btn btn-primary" data-action="create-invite">Create invitation link</button></div><div id="invite-result" style="margin-top:14px"></div><div class="modal-actions"><button class="btn" data-action="close-modal">Done</button></div>`);}
function manageMembersForm(selectedId=null){const list=state.allMembers.length?state.allMembers:state.members;const m=list.find(x=>x.id===Number(selectedId))||list[0];if(!m)return;showModal('Manage membership','Admins can update member accounts and normal band roles.',`<form id="member-admin-form" data-member-id="${m.id}"><div class="form-grid"><div class="field full"><label for="manage-member">Member</label><select id="manage-member" class="select" name="target_id">${selectOptions(list.map(x=>({value:x.id,label:`${x.display_name} (${x.email})${x.active?'':' · inactive'}`})),m.id,'')}</select></div><div class="field"><label for="manage-name">Display name</label><input id="manage-name" class="input" name="display_name" value="${esc(m.display_name)}" required></div><div class="field"><label for="manage-role">Account permission</label><select id="manage-role" class="select" name="role">${selectOptions([{value:'member',label:'Member'},{value:'admin',label:'Admin'}],m.role,'')}</select></div><div class="field full"><span class="field-label">Band roles</span>${['drummer','guitarist','bassist','other'].map(role=>`<label class="check-pill"><input type="checkbox" name="roles" value="${role}" ${(m.roles||[]).includes(role)?'checked':''}> ${role[0].toUpperCase()+role.slice(1)}</label>`).join('')}</div><div class="field full"><label class="checkbox-row"><input type="checkbox" name="active" value="1" ${m.active?'checked':''}> Active member</label></div></div><div id="form-error" class="error-text" hidden></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Done</button><button class="btn btn-primary" type="submit">Save member</button></div></form>`);}

function toggleAvailabilityFields(){const form=modal.querySelector('#availability-form');if(!form)return;const unavailable=form.querySelector('[name="unavailable"]').checked;form.querySelectorAll('.availability-time').forEach(el=>el.hidden=unavailable);form.querySelectorAll('.availability-time input').forEach(el=>el.required=!unavailable);const recurring=form.querySelector('[name="recurrence"]').value==='weekly';const until=form.querySelector('.weekly-until');if(until)until.hidden=!recurring;}
function updateCostEstimate(){const form=modal.querySelector('#rehearsal-form');if(!form)return;const locId=Number(form.elements.location_id.value);const location=state.locations.find(l=>l.id===locId);const area=form.querySelector('#cost-estimate');if(!area)return;if(!location){area.textContent='A venue with a saved rate will have its cost estimated from the rehearsal duration.';return}const start=form.elements.start_time.value,end=form.elements.end_time.value;if(!start||!end){area.textContent='';return}const [sh,sm]=start.split(':').map(Number),[eh,em]=end.split(':').map(Number);let duration=eh*60+em-(sh*60+sm);if(duration<=0){area.textContent='End time must be later than start time.';return}const estimate=location.flat_cost!=null?Number(location.flat_cost):location.hourly_rate!=null?Number(location.hourly_rate)*duration/60:null;area.textContent=estimate==null?`No rate saved for ${location.name}; enter a total cost if needed.`:`Estimated from ${location.name}: ${money(estimate)} for ${durationText(duration)}. Past rehearsal costs remain fixed.`;}

async function refreshAll(){await Promise.all([loadMembers(),loadSongs(),loadDashboard()]);if(state.tab==='practice')await refreshPractice();renderApp();}
function openCurrentPractice(){state.tab='practice';state.practice='rehearsals';renderApp();}

async function handleClick(event){
  const modeButton=event.target.closest('[data-auth-mode]');if(modeButton){state.authMode=modeButton.dataset.authMode;state.authNotice='';if(state.authMode==='login'&&location.hash)history.replaceState({},'',location.pathname);renderAuth({configured:state.configured});return}
  const tab=event.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;renderApp();return}
  const practice=event.target.closest('[data-practice]');if(practice){state.practice=practice.dataset.practice;state.overlap=null;renderApp();return}
  const actionButton=event.target.closest('[data-action]');if(!actionButton)return;
  const action=actionButton.dataset.action,id=Number(actionButton.dataset.id);
  try{
    if(action==='user-menu'){const pop=document.getElementById('user-popover');pop.classList.toggle('open');actionButton.setAttribute('aria-expanded',pop.classList.contains('open'));return}
    if(action==='close-modal'){closeModal();return}
    if(action==='new-song'){songForm();return}
    if(action==='song-detail'){await openSongDetail(id);return}
    if(action==='edit-song'){const song=state.openSong?.id===id?state.openSong:await api(`/api/songs/${id}`);songForm(song);return}
    if(action==='song-vote'){const r=await api(`/api/songs/${id}/vote`,{method:'POST',body:{}});toast(r.voted?'Vote added':'Vote removed');await loadSongs();if(state.openSong?.id===id)await openSongDetail(id);else renderApp();return}
    if(action==='song-add-next'){const next=state.dashboard?.next_rehearsal;if(!next){toast('Plan a rehearsal first, then add songs to its setlist.',true);openCurrentPractice();return}await api(`/api/rehearsals/${next.id}/songs`,{method:'POST',body:{song_id:id,version:next.version}});toast('Song added to the next rehearsal');await loadDashboard();renderApp();return}
    if(action==='delete-song'){if(!confirm('Delete this song from the shared library? Comments, votes, and rehearsal setlist entries will also be removed.'))return;await api(`/api/songs/${id}`,{method:'DELETE',body:{confirm:true,version:Number(actionButton.dataset.version)}});toast('Song deleted');closeModal();await loadSongs();await loadDashboard();renderApp();return}
    if(action==='edit-announcement'){const item=(state.dashboard?.announcements||[]).find(x=>x.id===id);if(item)announcementForm(item);return}
    if(action==='delete-announcement'){if(!confirm('Delete this announcement for everyone in the band? This cannot be undone.'))return;await api(`/api/announcements/${id}`,{method:'DELETE',body:{confirm:true,version:Number(actionButton.dataset.version)}});toast('Announcement deleted');await loadDashboard();renderApp();return}
    if(action==='pin-announcement'){await api(`/api/announcements/${id}`,{method:'PATCH',body:{pinned:actionButton.dataset.pinned==='1',version:Number(actionButton.dataset.version)}});toast(actionButton.dataset.pinned==='1'?'Announcement pinned':'Announcement unpinned');await loadDashboard();renderApp();return}
    if(action==='new-availability'){openAvailabilityForm(null,localDateString());return}
    if(action==='edit-availability'){const entry=state.availability.find(e=>e.id===id&&e.date===actionButton.dataset.date)||state.availability.find(e=>e.id===id);if(entry)openAvailabilityForm(entry);return}
    if(action==='delete-availability'){if(!confirm('Remove this availability entry?'))return;await api(`/api/availability/${id}`,{method:'DELETE',body:{version:Number(actionButton.dataset.version)}});toast('Availability removed');await loadAvailability();renderAppNoRefresh();return}
    if(action==='skip-availability'){if(!confirm(`Skip this recurring availability on ${actionButton.dataset.date}?`))return;await api(`/api/availability/${id}/exceptions`,{method:'POST',body:{date:actionButton.dataset.date}});toast('Date skipped');await loadAvailability();renderAppNoRefresh();return}
    if(action==='unskip-availability'){await api(`/api/availability/${id}/exceptions?date=${encodeURIComponent(actionButton.dataset.date)}`,{method:'DELETE',body:{}});toast('Availability restored for that date');await loadAvailability();const entry=state.availability.find(e=>e.id===id);if(entry)openAvailabilityForm(entry);else renderAppNoRefresh();return}
    if(action==='week-prev'||action==='week-next'){state.weekStart=addDays(state.weekStart,action==='week-prev'?-7:7);await loadAvailability();renderAppNoRefresh();return}
    if(action==='propose-slot'){const members=JSON.parse(actionButton.dataset.members||'[]');await loadLocations();rehearsalForm(null,{date:actionButton.dataset.date,start:actionButton.dataset.start,end:actionButton.dataset.end,members});return}
    if(action==='new-rehearsal'){await loadLocations();rehearsalForm();return}
    if(action==='rehearsal-detail'){await openRehearsalDetail(id);return}
    if(action==='download-calendar'){const rehearsal=state.rehearsals.find(item=>item.id===id)||await api(`/api/rehearsals/${id}`);downloadCalendar(rehearsal);toast('Calendar file downloaded');return}
    if(action==='edit-rehearsal'){const r=state.openRehearsal?.id===id?state.openRehearsal:await api(`/api/rehearsals/${id}`);await loadLocations();rehearsalForm(r);return}
    if(action==='delete-rehearsal'){if(!confirm('Delete this rehearsal and its setlist and cost tracking? This cannot be undone.'))return;await api(`/api/rehearsals/${id}`,{method:'DELETE',body:{confirm:true,version:Number(actionButton.dataset.version)}});toast('Rehearsal deleted');closeModal();await loadRehearsals();await loadDashboard();renderApp();return}
    if(action==='set-response'){const select=modal.querySelector(`[data-response-member="${actionButton.dataset.member}"]`);const target=Number(actionButton.dataset.member);const body={response:select.value};if(target!==state.member.id&&state.member.role==='admin')body.member_id=target;await api(`/api/rehearsals/${id}/response`,{method:'POST',body});toast('Attendance response saved');await openRehearsalDetail(id);return}
    if(action==='move-set-up'||action==='move-set-down'){const position=Number(actionButton.dataset.position);await api(`/api/rehearsals/${id}/songs`,{method:'POST',body:{song_id:Number(actionButton.dataset.song),position,version:Number(actionButton.dataset.version)}});await openRehearsalDetail(id);await loadDashboard();return}
    if(action==='remove-set-song'){if(!confirm('Remove this song from the rehearsal setlist?'))return;await api(`/api/rehearsals/${id}/songs`,{method:'DELETE',body:{song_id:Number(actionButton.dataset.song),version:Number(actionButton.dataset.version)}});await openRehearsalDetail(id);await loadDashboard();return}
    if(action==='toggle-paid'){await api(`/api/rehearsals/${id}/shares`,{method:'PATCH',body:{member_id:Number(actionButton.dataset.member),reimbursement_paid:actionButton.dataset.paid==='1'}});await openRehearsalDetail(id);return}
    if(action==='save-payer'){const payer=modal.querySelector('#venue-payer').value;await api(`/api/rehearsals/${id}/shares`,{method:'PATCH',body:{member_id:state.member.id,venue_paid_by_id:payer||null}});toast('Venue payment recorded');await openRehearsalDetail(id);return}
    if(action==='new-location'){locationForm();return}
    if(action==='edit-location'){const loc=state.locations.find(l=>l.id===id);if(loc)locationForm(loc);return}
    if(action==='delete-location'){if(!confirm('Delete this saved location? Past rehearsal address and cost records will remain.'))return;await api(`/api/locations/${id}`,{method:'DELETE',body:{confirm:true,version:Number(actionButton.dataset.version)}});toast('Location deleted');await loadLocations();renderAppNoRefresh();return}
    if(action==='profile'){profileForm();return}
    if(action==='invite'){inviteForm();return}
    if(action==='manage-members'){await loadAllMembers();manageMembersForm();return}
    if(action==='create-invite'){const result=await api('/api/invitations',{method:'POST',body:{}});const full=location.origin+result.invite_url;modal.querySelector('#invite-result').innerHTML=`<div class="success-box"><strong>Invitation link</strong><div style="word-break:break-all;margin:7px 0">${esc(full)}</div><div class="muted-note">Expires ${esc(fmtInstant(result.expires_at,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))}</div><button class="btn btn-small" data-action="copy-invite" data-value="${esc(full)}" style="margin-top:9px">Copy link</button></div>`;return}
    if(action==='copy-invite'){await navigator.clipboard.writeText(actionButton.dataset.value);toast('Invitation link copied');return}
    if(action==='reload-conflict-song'){const latest=JSON.parse(modal.dataset.conflict||'null');if(latest)songForm(latest);return}
    if(action==='reload-conflict-rehearsal'){const latest=JSON.parse(modal.dataset.conflict||'null');if(latest)rehearsalForm(latest);return}
    if(action==='logout'){await api('/api/logout',{method:'POST',body:{}});state.member=null;state.band=null;state.authMode='login';history.replaceState({},'',location.pathname);renderAuth({configured:true});return}
  }catch(error){toast(error.message,true)}
}

async function handleSubmit(event){
  const form=event.target;if(!form.id)return;
  event.preventDefault();const fd=new FormData(form);
  try{
    if(form.id==='auth-form'){
      const mode=form.dataset.mode;
      if(mode==='forgot'){
        await api('/api/password-reset/request',{method:'POST',body:{band_name:formValue(fd,'band_name'),email:formValue(fd,'email')}});
        state.authNotice='If the account matches this band and email, a reset link will arrive shortly. Check your inbox and spam folder.';renderAuth({configured:true});return;
      }
      if(mode==='reset'){
        await api('/api/password-reset/complete',{method:'POST',body:{token:fd.get('token'),password:fd.get('password'),password_confirmation:fd.get('password_confirmation')}});
        history.replaceState({},'',location.pathname);state.authMode='login';state.authNotice='Your password has been reset. Sign in with your new password.';renderAuth({configured:true});return;
      }
      const body={email:formValue(fd,'email'),password:fd.get('password')};if(mode!=='join')body.band_name=formValue(fd,'band_name');if(mode!=='login')body.display_name=formValue(fd,'display_name');if(mode==='join')body.token=fd.get('token');
      const route=mode==='login'?'/api/login':mode==='signup'?'/api/signup':'/api/join';await api(route,{method:'POST',body});const session=await api('/api/me');state.member=session.member;state.band=session.band;state.configured=true;state.weekStart=mondayOf(localDateString());await loadMembers();await loadSongs();await loadDashboard();history.replaceState({},'',location.pathname);renderApp();return;
    }
    if(form.id==='announcement-form'){
      await api('/api/announcements',{method:'POST',body:{body:formValue(fd,'body')}});
      toast('Announcement posted');await loadDashboard();renderApp();return;
    }
    if(form.id==='announcement-edit-form'){
      await api(`/api/announcements/${form.dataset.id}`,{method:'PATCH',body:{body:formValue(fd,'body'),version:Number(form.dataset.version)}});
      toast('Announcement updated');closeModal();await loadDashboard();renderApp();return;
    }
    if(form.id==='song-form'){
      const songId=form.dataset.songId;const body={title:formValue(fd,'title'),artist:formValue(fd,'artist'),status:formValue(fd,'status'),key_name:formValue(fd,'key_name'),bpm:formValue(fd,'bpm')||null,duration_minutes:formValue(fd,'duration_minutes')||null,difficulty:formValue(fd,'difficulty')||null,priority:Number(formValue(fd,'priority')||3),singer_ids:formIds(form,'singer_ids'),pianist_id:formValue(fd,'pianist_id')||null,performed_live:fd.has('performed_live'),performed_dates:formValue(fd,'performed_dates').split(/\n|,/).map(x=>x.trim()).filter(Boolean),tags:formValue(fd,'tags').split(',').map(x=>x.trim()).filter(Boolean),links:formValue(fd,'links').split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const i=line.indexOf('|');return {label:i<0?'Reference':line.slice(0,i).trim(),url:i<0?line.trim():line.slice(i+1).trim()}}),arrangement_notes:formValue(fd,'arrangement_notes'),practice_notes:formValue(fd,'practice_notes')};
      if(!songId&&!form.dataset.duplicateConfirmed){const matchList=await api(`/api/songs?q=${encodeURIComponent(body.title)}`);const duplicate=matchList.songs.find(s=>s.title.trim().toLowerCase()===body.title.toLowerCase()&&s.artist.trim().toLowerCase()===body.artist.toLowerCase());if(duplicate){const warning=form.querySelector('#duplicate-warning');warning.hidden=false;warning.textContent=`Possible duplicate: “${duplicate.title}” by ${duplicate.artist} is already in the library. Review it before continuing, or submit again to add another arrangement.`;form.dataset.duplicateConfirmed='true';form.querySelector('button[type="submit"]').textContent='Add anyway';return}}
      const result=songId?await api(`/api/songs/${songId}`,{method:'PATCH',body:{...body,version:Number(form.dataset.version)}}):await api('/api/songs',{method:'POST',body});
      if(!songId&&fd.has('add_to_next')&&state.dashboard?.next_rehearsal)await api(`/api/rehearsals/${state.dashboard.next_rehearsal.id}/songs`,{method:'POST',body:{song_id:result.id,version:state.dashboard.next_rehearsal.version}});
      toast(songId?'Song updated':'Song added');closeModal();await loadSongs();await loadDashboard();renderApp();return;
    }
    if(form.id==='comment-form'){const id=Number(form.dataset.songId);await api(`/api/songs/${id}/comments`,{method:'POST',body:{body:formValue(fd,'body')}});await openSongDetail(id);return}
    if(form.id==='availability-form'){
      const unavailable=fd.has('unavailable');const body={kind:unavailable?'unavailable':'available',start_date:formValue(fd,'start_date'),recurrence:formValue(fd,'recurrence'),until_date:formValue(fd,'until_date')||null,note:formValue(fd,'note')};if(!unavailable){body.start_time=formValue(fd,'start_time');body.end_time=formValue(fd,'end_time')}
      if(form.dataset.id)await api(`/api/availability/${form.dataset.id}`,{method:'PATCH',body:{...body,version:Number(form.dataset.version)}});else await api('/api/availability',{method:'POST',body});
      toast('Availability saved');closeModal();await loadAvailability();renderAppNoRefresh();return;
    }
    if(form.id==='overlap-form'){const required=formIds(form,'required_member_ids');if(!required.length)throw new Error('Select at least one required member.');const q=new URLSearchParams({from:formValue(fd,'from'),to:formValue(fd,'to'),min_minutes:formValue(fd,'min_minutes'),members:required.join(',')});state.overlap=await api(`/api/overlaps?${q}`);renderAppNoRefresh();return}
    if(form.id==='rehearsal-form'){
      const body={title:formValue(fd,'title'),event_type:formValue(fd,'event_type'),date:formValue(fd,'date'),start_time:formValue(fd,'start_time'),end_time:formValue(fd,'end_time'),status:formValue(fd,'status'),invited_ids:formIds(form,'invited_ids'),location_id:formValue(fd,'location_id')||null,recalculate_cost:fd.has('recalculate_cost'),location_name:formValue(fd,'location_name'),address:formValue(fd,'address'),room_number:formValue(fd,'room_number'),booking_link:formValue(fd,'booking_link'),booking_reference:formValue(fd,'booking_reference'),split_mode:formValue(fd,'split_mode'),split_member_ids:formIds(form,'split_member_ids'),goals:formValue(fd,'goals'),notes:formValue(fd,'notes'),summary:formValue(fd,'summary')};if(formValue(fd,'total_cost_cad'))body.total_cost_cad=Number(formValue(fd,'total_cost_cad'));
      const id=form.dataset.id;if(id){body.version=Number(form.dataset.version);await api(`/api/rehearsals/${id}`,{method:'PATCH',body})}else await api('/api/rehearsals',{method:'POST',body});
      toast(id?'Rehearsal updated':'Proposed rehearsal created');closeModal();await loadRehearsals();await loadDashboard();renderApp();return;
    }
    if(form.id==='setlist-form'){const id=Number(form.dataset.rehearsal);await api(`/api/rehearsals/${id}/songs`,{method:'POST',body:{song_id:formValue(fd,'song_id'),notes:formValue(fd,'notes'),version:Number(form.dataset.version)}});await openRehearsalDetail(id);await loadDashboard();return}
    if(form.id==='location-form'){
      const body={name:formValue(fd,'name'),address:formValue(fd,'address'),map_url:formValue(fd,'map_url'),booking_link:formValue(fd,'booking_link'),hourly_rate:formValue(fd,'hourly_rate')||null,flat_cost:formValue(fd,'flat_cost')||null,contact:formValue(fd,'contact'),equipment:formValue(fd,'equipment').split(',').map(x=>x.trim()).filter(Boolean),notes:formValue(fd,'notes')};if(form.dataset.id){body.version=Number(form.dataset.version);await api(`/api/locations/${form.dataset.id}`,{method:'PATCH',body})}else await api('/api/locations',{method:'POST',body});toast('Practice location saved');closeModal();await loadLocations();renderAppNoRefresh();return;
    }
    if(form.id==='profile-form') {const body={display_name:formValue(fd,'display_name'),roles:[...form.querySelectorAll('input[name="roles"]:checked')].map(i=>i.value),color:formValue(fd,'color')};const result=await api('/api/me',{method:'PATCH',body});state.member=result.member;await loadMembers();toast('Profile updated');closeModal();renderApp();return}
    if(form.id==='member-admin-form'){const target=Number(formValue(fd,'target_id'));const body={display_name:formValue(fd,'display_name'),role:formValue(fd,'role'),active:fd.has('active'),roles:[...form.querySelectorAll('input[name="roles"]:checked')].map(i=>i.value)};await api(`/api/members/${target}`,{method:'PATCH',body});await loadMembers();await loadAllMembers();state.member=state.members.find(m=>m.id===state.member.id)||state.member;toast('Member updated');manageMembersForm(target);return}
  }catch(error){if(form.id==='auth-form'){const box=form.querySelector('#form-error');if(box){box.textContent=error.message;box.hidden=false}}else if(error.status===409&&error.details){setFormError(error.message,error.details)}else if(modal.open&&modal.querySelector('#form-error'))setFormError(error.message);else toast(error.message,true)}
}

app.addEventListener('click',handleClick);
modal.addEventListener('click',handleClick);
document.addEventListener('submit',handleSubmit);
document.addEventListener('input',event=>{
  if(event.target.name==='song-search'){
    clearTimeout(state.searchTimer);state.searchTimer=setTimeout(async()=>{state.songsQuery.q=event.target.value;try{await loadSongs();const list=app.querySelector('.song-grid')?.parentElement;if(list){const old=app.querySelector('.song-grid')||app.querySelector('.empty-state');if(old)old.outerHTML=renderSongGrid();const count=app.querySelector('.song-count');if(count)count.textContent=`${state.songs.length} shown`}}catch(e){toast(e.message,true)}},180);
  }
});
document.addEventListener('change',async event=>{
  const f=event.target;
  if(f.matches('[data-filter]')){if(f.value)state.songsQuery[f.dataset.filter]=f.value;else delete state.songsQuery[f.dataset.filter];try{await loadSongs();const old=app.querySelector('.song-grid')||app.querySelector('.empty-state');if(old)old.outerHTML=renderSongGrid();const count=app.querySelector('.song-count');if(count)count.textContent=`${state.songs.length} shown`}catch(e){toast(e.message,true)}}
  if(f.closest('#availability-form')&&(f.name==='unavailable'||f.name==='recurrence'))toggleAvailabilityFields();
  if(f.closest('#rehearsal-form')&&(f.name==='location_id'||f.name==='start_time'||f.name==='end_time')){if(f.name==='location_id'){const location=state.locations.find(l=>l.id===Number(f.value));if(location){modal.querySelector('[name="location_name"]').value=location.name;modal.querySelector('[name="address"]').value=location.address||''}}updateCostEstimate()}
  if(f.closest('#rehearsal-form')&&f.name==='split_mode'){const field=modal.querySelector('.manual-split');if(field)field.hidden=f.value!=='selected'}
  if(f.id==='manage-member'){manageMembersForm(Number(f.value))}
});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.matches('.song-card')){event.preventDefault();openSongDetail(Number(event.target.dataset.id))}});

boot();
